package io.cloudsoft.winrm4j.client;

import java.util.Base64;
import java.util.UUID;

import io.cloudsoft.winrm4j.client.psrp.PsrpFragment;
import io.cloudsoft.winrm4j.client.psrp.PsrpMessageDefragmenter;
import io.cloudsoft.winrm4j.client.psrp.PsrpMessageFactory;
import io.cloudsoft.winrm4j.client.psrp.PsrpMessageFragmenter;
import io.cloudsoft.winrm4j.client.psrp.PsrpUtils;
import org.testng.Assert;
import org.testng.annotations.Test;

public class PsrpVerificationTest {

	@Test
	public void initPool() {
		final var shellId = UUID.fromString("66ee7d98-b951-4545-b550-b0a28278769d");
		final var fragmenter = new PsrpMessageFragmenter();
		final var actualBytes = PsrpUtils.buildOpenShellPayload(shellId, fragmenter);
		final var actual = Base64.getEncoder().encodeToString(
				actualBytes
		);
		final var actualDefragmenter = new PsrpMessageDefragmenter();
		final var actualFragments = PsrpFragment.readMulti(actualBytes);
		final var actualMessage1 = actualDefragmenter.defragment(actualFragments.get(0)).orElseThrow();
		final var actualMessage2 = actualDefragmenter.defragment(actualFragments.get(0)).orElseThrow();


		final var expected = "";
		final var expectedFragments = PsrpFragment.readMulti(Base64.getDecoder().decode(expected));
		final var expectedDefragmenter = new PsrpMessageDefragmenter();
		final var expectedMessage1 = expectedDefragmenter.defragment(expectedFragments.get(0)).orElseThrow();
		final var expectedMessage2 = expectedDefragmenter.defragment(expectedFragments.get(0)).orElseThrow();
		Assert.assertEquals(actualBytes, Base64.getDecoder().decode(expected));
		Assert.assertEquals(actual, expected);
	}

	@Test
	public void command() {
		final var shellId = UUID.fromString("66ee7d98-b951-4545-b550-b0a28278769d");
		final var commandId = UUID.fromString("c5ff2036-bc64-4a72-93ce-d8ac55d39309");
		final var actualMessage = PsrpMessageFactory.createPipeline(shellId, commandId, "Write-Output test");
		final var actualFragment = new PsrpMessageFragmenter().withObjectId(2).fragment(actualMessage)
				.get(0);
		final var actual = Base64.getEncoder().encodeToString(
				actualFragment.bytes()
		);
		final var expected = "";
		final var expectedFragment = PsrpFragment.read(Base64.getDecoder().decode(expected));
		final var expectedMessage = new PsrpMessageDefragmenter().defragment(expectedFragment).orElseThrow();
		Assert.assertEquals(actualMessage.data(), expectedMessage.data(), "no matching content");
		Assert.assertEquals(actualFragment.bytes(), Base64.getDecoder().decode(expected), "no matching content");
		Assert.assertEquals(actual, expected, "no matching content");
	}

}
